verus! {
    /// Given two Vec<i8> of equal length, produce a Vec<bool> of the same length
    /// where each entry indicates whether the corresponding entry of `a` (as i32)
    /// is strictly greater than that of `b` (as i32).
    fn greater(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
            forall|i: usize| i < a.len() ==>
                result[i] == ((a[i] as i32) > (b[i] as i32)),
    {
        let n = a.len();
        let mut result: Vec<bool> = Vec::new();
        let mut idx: usize = 0;
        while idx < n
            invariant
                idx <= n,
                result.len() == idx,
                forall|j: usize| j < idx ==>
                    result[j] == ((a[j] as i32) > (b[j] as i32)),
            decreases n - idx,
        {
            let ai = a[idx];
            let bi = b[idx];
            let cmp = (ai as i32) > (bi as i32);
            result.push(cmp);
            idx += 1;
        }
        result
    }
}

